    { id: 'market1', title: 'A Merchant’s Square', desc: 'Build a Market for trade and coin.', target: 1, reward: { gold: 90, wood: 40 }, xp: 20,
      check: s => s.stats.built.market >= 1, progress: s => `${Math.min(1, s.stats.built.market || 0)} / 1` },
    { id: 'people20', title: 'The Township Blooms', desc: 'Grow the population to 20 souls.', target: 20, reward: { food: 100, gold: 60 }, xp: 25,
      check: s => s.pop >= 20, progress: s => `${s.pop} / 20` },
    { id: 'chapel1', title: 'A Steeple to the Sky', desc: 'Build a Chapel for your people.', target: 1, reward: { gold: 110, stone: 35 }, xp: 25,
      check: s => s.stats.built.chapel >= 1, progress: s => `${Math.min(1, s.stats.built.chapel || 0)} / 1` },
    { id: 'level4', title: 'A Borough of Note', desc: 'Reach renown level 4.', target: 4, reward: { wood: 80, gold: 100 }, xp: 30,
      check: s => s.level >= 4, progress: s => `Level ${s.level} / 4` },
    { id: 'barracks1', title: 'Guards of Valewood', desc: 'Build a Barracks to protect the realm.', target: 1, reward: { gold: 160, stone: 50 }, xp: 40,
      check: s => s.stats.built.barracks >= 1, progress: s => `${Math.min(1, s.stats.built.barracks || 0)} / 1` }
  ];

  const START_BUILDINGS = [
    { type: 'keep', x: 6, y: 4 },
    { type: 'house', x: 3, y: 3, variant: 1 },
    { type: 'house', x: 8, y: 4, variant: 2 },
    { type: 'house', x: 4, y: 6, variant: 3 },
    { type: 'house', x: 8, y: 6, variant: 1 },
    { type: 'well', x: 6, y: 6 },
    { type: 'farm', x: 2, y: 6 },
    { type: 'lumber', x: 9, y: 7 },
    { type: 'road', x: 3, y: 4 }, { type: 'road', x: 2, y: 5 }, { type: 'road', x: 3, y: 5 },
    { type: 'road', x: 4, y: 5 }, { type: 'road', x: 5, y: 5 }, { type: 'road', x: 6, y: 5 },
    { type: 'road', x: 7, y: 5 }, { type: 'road', x: 8, y: 5 }, { type: 'road', x: 9, y: 5 },
    { type: 'road', x: 9, y: 6 }
  ];

  G.START_BUILDINGS = START_BUILDINGS;

  // ---------- utility ----------
  G.hash = function (x, y, salt = 0) {
    const n = Math.sin(x * 127.1 + y * 311.7 + salt * 74.7) * 43758.5453123;
    return n - Math.floor(n);
  };
  G.key = (x, y) => `${x},${y}`;
  G.clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  G.round = (v, p = 1) => {
    const f = Math.pow(10, p);
    return Math.round(v * f) / f;
  };
  G.fmt = function (v) {
    if (v >= 10000) return (v / 1000).toFixed(1) + 'k';
    if (v >= 1000) return Math.round(v).toLocaleString('en-US');
    return `${Math.floor(v)}`;
  };
  G.perMin = function (v) {
    const n = v * 60;
    const abs = Math.abs(n);
    const sign = n >= 0 ? '+' : '−';
    if (abs < .05) return '—';
    return sign + (abs < 10 ? abs.toFixed(1) : Math.round(abs));
  };
  G.day = s => 1 + Math.floor((s.playTime || 0) / 80);
  G.season = s => G.SEASONS[Math.floor((G.day(s) - 1) / 4) % 4];
  G.levelData = lvl => G.LEVELS[G.clamp(lvl, 1, G.MAX_LEVEL) - 1];

  G.levelForXp = function (xp) {
    let l = 1;
    for (const row of G.LEVELS) if (xp >= row.xp) l = row.level;
    return l;
  };

  G.buildingAt = function (x, y, state = G.state) {
    if (!state) return null;
    return state.buildings.find(b => b.x === x && b.y === y) || null;
  };

  G.effective = function (b) {
    const def = G.BUILDINGS[b.type];
    if (!def) return null;
    const lv = b.level || 1;
    const mult = 1 + (lv - 1) * .5;
    const jobs = def.jobs ? def.jobs + (lv - 1) : 0;
    const capacity = def.capacity ? def.capacity + (lv - 1) * 2 : 0;
    const production = {};
    const consumption = {};
    for (const k in def.production || {}) production[k] = def.production[k] * mult;
    for (const k in def.consumption || {}) consumption[k] = def.consumption[k] * mult;
    return { def, mult, jobs, capacity, production, consumption, happiness: def.happiness || 0 };
  };

  // ---------- static map ----------
  G.terrain = [];
  G.scenery = [];
  G.pond = new Set(['2,8', '3,8', '2,9', '3,9']);
  G.forestTiles = [
    [0, 0], [1, 0], [2, 0], [0, 1], [1, 1], [0, 2],
    [10, 1], [11, 0], [11, 1], [11, 2], [9, 2], [10, 2], [10, 3],
    [0, 8], [1, 8], [1, 9], [11, 8]
  ];
  G.rockTiles = [[11, 3], [0, 7]];

  function makeMap() {
    G.terrain = [];
    for (let y = 0; y < G.MAP_H; y++) {
      const row = [];
      for (let x = 0; x < G.MAP_W; x++) {
        let kind = 'grass';
        if (x >= 12 || y >= 10 || G.pond.has(G.key(x, y))) kind = 'water';
        if (G.forestTiles.some(p => p[0] === x && p[1] === y)) kind = 'forest';
        if (G.rockTiles.some(p => p[0] === x && p[1] === y)) kind = 'rock';
        row.push({ kind, blocked: kind !== 'grass', variant: Math.floor(G.hash(x, y, 3) * 4) });
      }
      G.terrain.push(row);
    }

    const scenery = [];
    for (const [x, y] of G.forestTiles) {
      const n = 2 + Math.floor(G.hash(x, y, 1) * 2);
      for (let i = 0; i < n; i++) {
        const h = G.hash(x, y, i + 10);
        const type = h < .38 ? 'oak1' : h < .63 ? 'oak2' : h < .86 ? 'pine1' : 'pine2';
        scenery.push({
          x, y, sprite: type,
          dx: (G.hash(x, y, i + 20) - .5) * .6,
          dy: (G.hash(x, y, i + 30) - .5) * .32,
          scale: .72 + G.hash(x, y, i + 40) * .32,
          sort: G.hash(x, y, i + 50) * .3
        });
      }
      if (G.hash(x, y, 2) > .35) scenery.push({ x, y, sprite: 'bush', dx: (G.hash(x, y, 3) - .5) * .55, dy: .2, scale: .6, sort: .55 });
    }
    for (const [x, y] of G.rockTiles) {
      scenery.push({ x, y, sprite: 'rock', dx: 0, dy: .06, scale: 1, sort: .1 });
    }
    // wild flowers & shrubs tucked into the edges of the realm
    const decorTiles = [[2, 2], [4, 2], [7, 2], [0, 3], [11, 4], [2, 7], [10, 6], [0, 6], [7, 9], [11, 7], [5, 9], [1, 4]];
    for (const [x, y] of decorTiles) {
      const h = G.hash(x, y, 7);
      const sprite = h < .45 ? 'flowers' : h < .8 ? 'bush' : 'fence';
      if (G.terrain[y] && G.terrain[y][x] && G.terrain[y][x].kind === 'grass') {
        scenery.push({ x, y, sprite, dx: (G.hash(x, y, 8) - .5) * .44, dy: .18, scale: sprite === 'fence' ? .7 : .72, sort: .45, decor: true });
      }
    }
    // reeds at the pond
    for (const [x, y] of G.pond) {
      scenery.push({ x, y, sprite: 'flowers', dx: .28, dy: .1, scale: .42, sort: .6, decor: true, water: true });
    }
    G.scenery = scenery;
  }
  makeMap();

  G.terrainAt = (x, y) => (G.terrain[y] && G.terrain[y][x]) || null;

  // ---------- state ----------
  G.newGame = function () {
    const buildings = START_BUILDINGS.map((b, i) => ({
      id: 'b' + (i + 1), type: b.type, x: b.x, y: b.y, level: 1,
      variant: b.variant || 1, built: 0
    }));
    const built = {};
    for (const b of buildings) built[b.type] = (built[b.type] || 0) + 1;
    G.state = {
      version: 1, name: 'Valewood',
      resources: { wood: 160, stone: 90, food: 150, gold: 110 },
      pop: 8, xp: 38, level: 1, tax: 'normal',
      festival: 0, growth: 0, decline: 0, playTime: 0,
      buildings, completedQuests: [], built,
      stats: { totalBuilt: buildings.length, upgrades: 0, peakPop: 8, questsDone: 0 },
      soundOn: true, nextId: buildings.length + 1,
      lastSaved: 0, dirty: true
    };
    G.recountBuilt();
    G.state.level = G.levelForXp(G.state.xp);
    return G.state;
  };

  G.recountBuilt = function () {
    const built = {};
    for (const b of G.state.buildings) built[b.type] = (built[b.type] || 0) + 1;
    G.state.built = built;
  };

  G.addXp = function (amount, silent = false) {
    if (!amount) return;
    const s = G.state;
    s.xp += amount;
    const next = G.levelForXp(s.xp);
    if (next > s.level) {
      const old = s.level;
      s.level = next;
      for (let lv = old + 1; lv <= next; lv++) {
        const row = G.levelData(lv);
        const unlocked = G.BUILD_ORDER.filter(t => G.BUILDINGS[t].unlock === lv).map(t => G.BUILDINGS[t].name);
        const note = unlocked.length ? `${unlocked.join(', ')} unlocked.` : 'Your realm grows in renown.';
        G.toast(`Renown level ${lv} — ${row.title}`, note, 'good', '♛');
      }
      G.emitFx('levelup');
      s.dirty = true;
    }
    return next;
  };

  G.toast = function (title, msg, kind = '', icon = '✦') {
    window.dispatchEvent(new CustomEvent('kb:toast', { detail: { title, msg, kind, icon } }));
  };

  G.emitFx = function (kind, data = {}) {
    window.dispatchEvent(new CustomEvent('kb:fx', { detail: { kind, ...data } }));
  };

  G.snapshot = function () {
    const s = G.state;
    let jobs = 0, capacity = 0, baseHappy = 0, defence = 0;
    for (const b of s.buildings) {
      const e = G.effective(b);
      if (!e) continue;
      jobs += e.jobs;
      capacity += e.capacity;
      baseHappy += e.happiness;
      defence += (e.def.defence || 0) * (b.level || 1);
    }

    // road network
    const roadSet = new Set();
    const roads = [];
    let keep = null;
    for (const b of s.buildings) {
      if (b.type === 'road') roads.push(b);
      if (b.type === 'keep') keep = b;
    }
    if (keep) {
      const roadAt = new Map(roads.map(r => [G.key(r.x, r.y), r]));
      const queue = [];
      const pushNeighbours = (x, y) => {
        for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const k = G.key(x + dx, y + dy);
          if (roadAt.has(k) && !roadSet.has(k)) { roadSet.add(k); queue.push(roadAt.get(k)); }
        }
      };
      pushNeighbours(keep.x, keep.y);
      while (queue.length) {
        const r = queue.shift();
        pushNeighbours(r.x, r.y);
      }
    }

    const buildingMap = new Map(s.buildings.map(b => [G.key(b.x, b.y), b]));
    const isConnected = b => {
      if (b.type === 'keep') return true;
      if (b.type === 'road') return roadSet.has(G.key(b.x, b.y));
      if (!keep) return false;
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const n = buildingMap.get(G.key(b.x + dx, b.y + dy));
        if (!n) continue;
        if (n.type === 'keep') return true;
        if (n.type === 'road' && roadSet.has(G.key(n.x, n.y))) return true;
      }
      return false;
    };

    const foodShortage = s.resources.food <= .1;
    const lowFood = s.resources.food < Math.max(10, s.pop * 1.2);
    const employed = Math.min(s.pop, jobs);
    const unemployment = jobs > 0 ? Math.max(0, s.pop - jobs) / Math.max(1, s.pop) : (s.pop > 0 ? 1 : 0);
    const overcrowded = capacity > 0 && s.pop > capacity;
    const taxMod = G.TAX[s.tax] || G.TAX.normal;
    let happiness = 55 + baseHappy;
    happiness += Math.min(10, roadSet.size * .7);
    happiness += taxMod.happy;
    if (foodShortage) happiness -= 28;
    else if (lowFood) happiness -= 5;
    if (unemployment > .12) happiness -= Math.min(8, unemployment * 9);
    if (overcrowded) happiness -= 14;
    if (s.festival > 0) happiness += 12;
    if (!s.buildings.some(b => b.type === 'house')) happiness -= 10;
    happiness = G.clamp(happiness, 4, 100);

    const productivity = .58 + .42 * (happiness / 100);
    const satisfied = employed / Math.max(1, s.pop);
    const staffFactor = jobs > 0 ? G.clamp(s.pop / jobs, 0, 1) : 1;

    const gross = { wood: 0, stone: 0, food: 0, gold: 0 };
    const consume = { wood: 0, stone: 0, food: 0, gold: 0 };
    const items = [];
    for (const b of s.buildings) {
      const e = G.effective(b);
      if (!e) continue;
      const connected = isConnected(b);
      const isProducer = Object.keys(e.production).length > 0;
      if (!isProducer) continue;
      const roadBonus = connected && b.type !== 'keep' ? 1.2 : 1;
      const mult = productivity * staffFactor * roadBonus;
      const prod = {};
      const cons = {};
      for (const k in e.production) { prod[k] = e.production[k] * mult; gross[k] += prod[k]; }
      for (const k in e.consumption) { cons[k] = e.consumption[k] * Math.max(.35, staffFactor); consume[k] += cons[k]; }
      items.push({ b, e, connected, prod, cons });
    }

    const taxGold = s.pop * .0042 * taxMod.mult * (.55 + happiness / 220);
    const foodEat = s.pop * .018;
    gross.gold += taxGold;
    consume.food += foodEat;
    const net = {};
    for (const k of resourceOrder) net[k] = gross[k] - consume[k];

    return {
      jobs, capacity, employed, satisfaction: satisfied, staffFactor, happiness,
      productivity, defence, roadCount: roadSet.size, roads: roadSet,
      isConnected, items, gross, consume, net, taxGold, foodEat,
      foodShortage, lowFood, overcrowded, unemployment
    };
  };

  G.connected = function (b) {
    if (!b) return false;
    const keep = G.state.buildings.find(x => x.type === 'keep');
    if (!keep) return false;
    if (b.type === 'keep') return true;
    const roadSet = new Set();
    const roads = G.state.buildings.filter(x => x.type === 'road');
    const roadAt = new Map(roads.map(r => [G.key(r.x, r.y), r]));
    const queue = [];
    const push = (x, y) => {
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const k = G.key(x + dx, y + dy);
        if (roadAt.has(k) && !roadSet.has(k)) { roadSet.add(k); queue.push(roadAt.get(k)); }
      }
    };
    push(keep.x, keep.y);
    while (queue.length) { const r = queue.shift(); push(r.x, r.y); }
    if (b.type === 'road') return roadSet.has(G.key(b.x, b.y));
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const n = G.buildingAt(b.x + dx, b.y + dy);
      if (n && (n.type === 'keep' || (n.type === 'road' && roadSet.has(G.key(n.x, n.y))))) return true;
    }
    return false;
  };

  G.happyNote = function (eco) {
    if (eco.foodShortage) return 'The granary is empty — your people are hungry.';
    if (eco.overcrowded) return 'Houses are crowded. Raise more homes.';
    if (eco.unemployment > .18) return 'Many hands are idle. Build more workplaces.';
    if (G.state.festival > 0) return 'Music and lanterns fill the square!';
    if (eco.happiness >= 86) return 'Valewood is the envy of the valley.';
    if (eco.happiness >= 68) return 'Your people are content and hopeful.';
    if (eco.happiness >= 50) return 'Life is modest, but the hearths are warm.';
    if (eco.happiness >= 34) return 'Discontent murmurs in the lanes.';
    return 'The people are unhappy. Something must change.';
  };

  G.levelProgress = function () {
    const s = G.state;
    const cur = G.levelData(s.level);
    const next = G.levelData(Math.min(G.MAX_LEVEL, s.level + 1));
    if (s.level >= G.MAX_LEVEL) return { pct: 100, text: `${Math.floor(s.xp)} renown`, next: 'A legend among kingdoms' };
    const span = next.xp - cur.xp;
    const pct = G.clamp(((s.xp - cur.xp) / span) * 100, 0, 100);
    return { pct, text: `${Math.floor(s.xp)} / ${next.xp} renown`, next: `Next: ${next.title}` };
  };

  G.questProgress = q => (q.progress ? q.progress(G.state) : '');
  G.activeQuests = function () {
    return G.QUESTS.filter(q => !G.state.completedQuests.includes(q.id)).slice(0, 3);
  };

  G.checkQuests = function () {
    const s = G.state;
    if (!s) return false;
    let changed = false;
    for (const q of G.QUESTS) {
      if (s.completedQuests.includes(q.id)) continue;
      if (q.check(s)) {
        s.completedQuests.push(q.id);
        s.stats.questsDone = (s.stats.questsDone || 0) + 1;
        for (const k in q.reward) s.resources[k] = (s.resources[k] || 0) + q.reward[k];
        G.toast('Decree fulfilled', `${q.title} — ${G.rewardText(q.reward)}`, 'good', '✓');
        G.addXp(q.xp || 0);
        changed = true;
        s.dirty = true;
        G.emitFx('quest');
      }
    }
    return changed;
  };

  G.rewardText = function (reward) {
    return Object.entries(reward).map(([k, v]) => `+${v} ${k}`).join(' · ');
  };

  G.canPlace = function (type, x, y, checkCost = true) {
    const def = G.BUILDINGS[type];
    if (!def || !def.buildable) return { ok: false, reason: 'This cannot be built.' };
    if (x < 0 || y < 0 || x >= G.MAP_W || y >= G.MAP_H) return { ok: false, reason: 'Beyond the edge of the realm.' };
    const tile = G.terrainAt(x, y);
    if (!tile) return { ok: false, reason: 'Beyond the edge of the realm.' };
    if (tile.kind === 'water') return { ok: false, reason: 'You cannot build on water.' };
    if (tile.kind === 'forest') return { ok: false, reason: 'The old forest will not yield.' };
    if (tile.kind === 'rock') return { ok: false, reason: 'The ground is too stony here.' };
    if (G.buildingAt(x, y)) return { ok: false, reason: 'This plot is already occupied.' };
    if (type === 'road' && G.buildingAt(x, y)) return { ok: false, reason: 'This plot is occupied.' };
    if (def.unique && G.state.buildings.some(b => b.type === type)) return { ok: false, reason: 'Only one may be raised.' };
    if (checkCost) {
      for (const [k, v] of Object.entries(def.cost)) {
        if ((G.state.resources[k] || 0) < v) return { ok: false, reason: `Not enough ${k}.`, missing: k };
      }
    }
    return { ok: true };
  };

  G.place = function (type, x, y) {
    const check = G.canPlace(type, x, y, true);
    if (!check.ok) {
      G.toast('Cannot build there', check.reason, 'bad', '✕');
      return check;
    }
    const def = G.BUILDINGS[type];
    for (const [k, v] of Object.entries(def.cost)) G.state.resources[k] -= v;
    const b = {
      id: 'b' + (G.state.nextId++), type, x, y, level: 1,
      variant: 1 + Math.floor(G.hash(x, y, G.state.nextId) * 3), built: G.day(G.state)
    };
    G.state.buildings.push(b);
    G.state.built[type] = (G.state.built[type] || 0) + 1;
    G.state.stats.totalBuilt = (G.state.stats.totalBuilt || 0) + 1;
    G.addXp(def.xp || 0);
    G.state.dirty = true;
    G.emitFx('build', { x, y });
    G.checkQuests();
    return { ok: true, building: b };
  };

  G.upgradeCost = function (b) {
    const def = G.BUILDINGS[b.type];
    if (!def || !def.buildable) return {};
    const factor = (b.level || 1) === 1 ? .7 : 1.2;
    const out = {};
    for (const [k, v] of Object.entries(def.cost)) out[k] = Math.max(5, Math.ceil((v * factor) / 5) * 5);
    return out;
  };

  G.canUpgrade = function (b) {
    const def = G.BUILDINGS[b.type];
    if (!def || (b.level || 1) >= (def.maxLevel || 1)) return { ok: false, reason: 'Already fully upgraded.' };
    const cost = G.upgradeCost(b);
    for (const [k, v] of Object.entries(cost)) if ((G.state.resources[k] || 0) < v) return { ok: false, reason: `Need ${v} ${k}.`, missing: k };
    return { ok: true, cost };
  };

  G.upgrade = function (id) {
    const b = G.state.buildings.find(x => x.id === id);
    if (!b) return false;
    const check = G.canUpgrade(b);
    if (!check.ok) { G.toast('Cannot upgrade', check.reason, 'bad', '✕'); return false; }
    for (const [k, v] of Object.entries(check.cost)) G.state.resources[k] -= v;
    b.level += 1;
    G.state.stats.upgrades = (G.state.stats.upgrades || 0) + 1;
    G.addXp(12 + b.level * 8);
    G.state.dirty = true;
    G.emitFx('upgrade', { x: b.x, y: b.y });
    G.toast(`${G.BUILDINGS[b.type].name} upgraded`, `Now level ${b.level}. Production and capacity increased.`, 'good', '⬆');
    return true;
  };

  G.demolish = function (id) {
    const i = G.state.buildings.findIndex(x => x.id === id);
    if (i < 0) return false;
    const b = G.state.buildings[i];
    const def = G.BUILDINGS[b.type];
    if (b.type === 'keep') { G.toast('The Keep stands', 'The heart of your realm cannot be demolished.', 'bad', '✕'); return false; }
    const refund = {};
    for (const [k, v] of Object.entries(def.cost)) {
      const amount = Math.max(1, Math.floor(v * .4));
      refund[k] = amount;
      G.state.resources[k] += amount;
    }
    G.state.buildings.splice(i, 1);
    G.recountBuilt();
    G.state.dirty = true;
    G.emitFx('demolish', { x: b.x, y: b.y });
    G.toast(`${def.name} removed`, `Salvaged ${Object.entries(refund).map(([k, v]) => `${v} ${k}`).join(' · ')}.`, '', '⌫');
    return true;
  };

  G.holdFestival = function () {
    const s = G.state;
    if (s.festival > 0) return false;
    if (s.resources.food < 30 || s.resources.gold < 25) {
      G.toast('The festival cannot begin', 'It requires 30 food and 25 gold.', 'bad', '✦');
      return false;
    }
    s.resources.food -= 30;
    s.resources.gold -= 25;
    s.festival = 45;
    s.dirty = true;
    G.toast('A festival begins!', 'Music, mead and merriment raise contentment for 45 seconds.', 'good', '✦');
    G.emitFx('festival');
    return true;
  };

  G.setTax = function (tax) {
    if (!G.TAX[tax]) return;
    G.state.tax = tax;
    G.state.dirty = true;
    G.emitFx('tax');
  };

  // ---------- simulation ----------
  G.simulate = function (dt) {
    const s = G.state;
    if (!s) return;
    const eco = G.snapshot();
    s.happiness = eco.happiness;
    s.capacity = eco.capacity;
    s.jobs = eco.jobs;

    for (const item of eco.items) {
      let ratio = 1;
      for (const k in item.cons) {
        if (item.cons[k] <= 0) continue;
        ratio = Math.min(ratio, (s.resources[k] || 0) / Math.max(.00001, item.cons[k] * dt));
      }
      ratio = G.clamp(ratio, 0, 1);
      for (const k in item.prod) s.resources[k] += item.prod[k] * dt * ratio;
      for (const k in item.cons) s.resources[k] -= item.cons[k] * dt * ratio;
    }
    s.resources.gold += eco.taxGold * dt;
    s.resources.food -= eco.foodEat * dt;
    for (const k of resourceOrder) s.resources[k] = G.clamp(s.resources[k], 0, 999999);

    if (s.festival > 0) {
      s.festival = Math.max(0, s.festival - dt);
      if (s.festival === 0) G.toast('The festival ends', 'The lanterns are dimmed, but the memory remains.', '', '✦');
    }

    const capacity = eco.capacity;
    const canGrow = s.pop < capacity && s.resources.food > 15 && eco.happiness >= 45;
    if (canGrow) {
      s.growth += dt;
      const interval = Math.max(11, 26 - eco.happiness * .12);
      if (s.growth >= interval) {
        s.growth = 0;
        s.pop += 1;
        s.stats.peakPop = Math.max(s.stats.peakPop || 0, s.pop);
        G.addXp(5, true);
        G.toast('New villagers arrive', `Valewood now has ${s.pop} souls.`, 'good', '♟');
        G.emitFx('growth');
        G.checkQuests();
        s.dirty = true;
      }
    } else {
      s.growth = Math.max(0, s.growth - dt * .55);
    }

    if (s.resources.food <= 0 && eco.happiness < 32) {
      s.decline += dt;
      if (s.decline > 35 && s.pop > 1) {
        s.decline = 0;
        s.pop -= 1;
        G.toast('A family departs', 'Hunger has driven a family from Valewood.', 'bad', '☹');
        s.dirty = true;
      }
    } else s.decline = Math.max(0, s.decline - dt);

    s.playTime += dt;
    s.dirty = true;
    G.questTimer = (G.questTimer || 0) + dt;
    if (G.questTimer > 1.2) { G.questTimer = 0; G.checkQuests(); }
  };

  // ---------- persistence ----------
  G.saveGame = function (manual = false) {
    try {
      const s = G.state;
      s.lastSaved = Date.now();
      s.dirty = false;
      localStorage.setItem(G.SAVE_KEY, JSON.stringify(s));
      window.dispatchEvent(new CustomEvent('kb:saved', { detail: { manual, at: s.lastSaved } }));
      if (manual) G.toast('Chronicle saved', 'Your kingdom is recorded in the royal archives.', 'good', '✎');
      return true;
    } catch (e) {
      if (manual) G.toast('Could not save', 'The chronicle could not be written to this browser.', 'bad', '✕');
      return false;
    }
  };

  G.hasSave = function () {
    try { return !!localStorage.getItem(G.SAVE_KEY); } catch { return false; }
  };

  G.loadGame = function () {
    try {
      const raw = localStorage.getItem(G.SAVE_KEY);
      if (!raw) return false;
      const data = JSON.parse(raw);
      if (!data || !Array.isArray(data.buildings)) return false;
      const base = G.newGame();
      const s = {
        ...base, ...data,
        resources: { ...base.resources, ...(data.resources || {}) },
        stats: { ...base.stats, ...(data.stats || {}) },
        buildings: data.buildings.filter(b => b && G.BUILDINGS[b.type] && Number.isInteger(b.x) && Number.isInteger(b.y))
          .map((b, i) => ({ ...b, level: G.clamp(b.level || 1, 1, G.BUILDINGS[b.type].maxLevel || 1), id: b.id || 'b' + (i + 100) }))
      };
      G.state = s;
      G.recountBuilt();
      s.level = G.levelForXp(s.xp || 0);
      s.pop = G.clamp(+s.pop || 1, 1, 9999);
      s.tax = G.TAX[s.tax] ? s.tax : 'normal';
      if (!Array.isArray(s.completedQuests)) s.completedQuests = [];
      s.dirty = false;
      G.checkQuests();
      window.dispatchEvent(new CustomEvent('kb:loaded'));
      return true;
    } catch (e) {
      console.warn('Could not load save', e);
      return false;
    }
  };

  G.deleteSave = function () {
    try { localStorage.removeItem(G.SAVE_KEY); } catch { /* noop */ }
  };

  G.costText = function (cost) {
    return Object.entries(cost).map(([k, v]) => `${v} ${k}`).join(' · ');
  };

  G.newGame();
})();

/* Kingdom Builder — canvas world, isometric renderer and map interaction. */
(function () {
  'use strict';
  const G = window.KBG;
  const KB = window.KBArt;
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');

  let DPR = 1, vw = 0, vh = 0, waterPattern = null;
  const images = {};
  const hitObjects = [];
  const particles = [];
  let lastFrame = 0, artLoaded = 0, artTotal = 0;

  G.camera = { userZoom: 1, panX: 0, panY: 0, scale: 1, base: 1, ox: 0, oy: 0, minZoom: .78, maxZoom: 1.7 };
  G.ui = { buildType: null, demolish: false, selected: null, hover: null, dragging: false };
  G.hitObjects = hitObjects;

  const pointers = new Map();
  let drag = null;
  let pinch = null;
  let suppressTap = false;

  function loadSprite(key, svg) {
    return new Promise(resolve => {
      const img = new Image();
      img.onload = () => { images[key] = img; artLoaded++; resolve(img); };
      img.onerror = () => { artLoaded++; resolve(null); };
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    });
  }

  G.loadArt = function () {
    const entries = Object.entries(KB.sprites);
    artTotal = entries.length;
    return Promise.all(entries.map(([k, v]) => loadSprite(k, v)));
  };

  function buildWaterPattern() {
    const c = document.createElement('canvas');
    c.width = 360; c.height = 360;
    const x = c.getContext('2d');
    const grad = x.createLinearGradient(0, 0, 0, 360);
    grad.addColorStop(0, '#1e4b53');
    grad.addColorStop(.5, '#245c63');
    grad.addColorStop(1, '#1b464f');
    x.fillStyle = grad;
    x.fillRect(0, 0, 360, 360);
    for (let i = 0; i < 70; i++) {
      const px = Math.random() * 360, py = Math.random() * 360;
      const len = 5 + Math.random() * 24;
      x.beginPath();
      x.moveTo(px, py);
      x.quadraticCurveTo(px + len * .45, py - 2 - Math.random() * 2, px + len, py);
      x.strokeStyle = `rgba(159,211,205,${.025 + Math.random() * .075})`;
      x.lineWidth = .7 + Math.random() * .8;
      x.stroke();
    }
    for (let i = 0; i < 90; i++) {
      x.fillStyle = `rgba(2,25,27,${.04 + Math.random() * .08})`;
      x.beginPath();
      x.arc(Math.random() * 360, Math.random() * 360, .7 + Math.random() * 2.4, 0, Math.PI * 2);
      x.fill();
    }
    return ctx.createPattern(c, 'repeat');
  }

  function updateCamera() {
    const small = vw < 760;
    const landscape = vh < 560;
    const fitW = (vw - 22) / 1250;
    const fitH = (vh - (small ? 118 : 188)) / 625;
    let base = Math.min(fitW, fitH);
    if (small) base = Math.max(base, .68);
    if (landscape) base = Math.min(base, .58);
    base = G.clamp(base, .38, 1.16);
    G.camera.base = base;
    G.camera.scale = base * G.camera.userZoom;
    const s = G.camera.scale;
    G.camera.ox = vw / 2 - 75 * s + G.camera.panX;
    G.camera.oy = (small ? vh * .475 : vh * .5) - 287.5 * s + G.camera.panY;
  }

  function clampPan() {
    const small = vw < 760;
    const maxX = small ? 360 : 170;
    const maxY = small ? 250 : 100;
    G.camera.panX = G.clamp(G.camera.panX, -maxX, maxX);
    G.camera.panY = G.clamp(G.camera.panY, -maxY, maxY);
  }

  function project(x, y) {
    const s = G.camera.scale;
    return {
      x: G.camera.ox + (x - y) * G.TW * .5 * s,
      y: G.camera.oy + (x + y) * G.TH * .5 * s
    };
  }

  G.screenToTile = function (sx, sy) {
    const s = G.camera.scale;
    const dx = (sx - G.camera.ox) / (G.TW * .5 * s);
    const dy = (sy - G.camera.oy) / (G.TH * .5 * s);
    const x = Math.round((dx + dy) / 2);
    const y = Math.round((dy - dx) / 2);
    return { x, y };
  };

  G.project = project;

  G.resizeWorld = function () {
    DPR = Math.min(2, window.devicePixelRatio || 1);
    vw = window.innerWidth; vh = window.innerHeight;
    canvas.width = Math.floor(vw * DPR);
    canvas.height = Math.floor(vh * DPR);
    canvas.style.width = vw + 'px';
    canvas.style.height = vh + 'px';
    updateCamera();
    if (!waterPattern) waterPattern = buildWaterPattern();
  };

  function diamond(cx, cy, w, h, inset = 0) {
    const halfW = Math.max(1, w / 2 - inset);
    const halfH = Math.max(1, h / 2 - inset);
    ctx.beginPath();
    ctx.moveTo(cx, cy - halfH);
    ctx.lineTo(cx + halfW, cy);
    ctx.lineTo(cx, cy + halfH);
    ctx.lineTo(cx - halfW, cy);
    ctx.closePath();
  }

  function drawWater(t) {
    ctx.fillStyle = '#173f48';
    ctx.fillRect(0, 0, vw, vh);
    const bg = ctx.createLinearGradient(0, 0, 0, vh);
    bg.addColorStop(0, 'rgba(35,82,86,.72)');
    bg.addColorStop(.48, 'rgba(28,73,80,.26)');
    bg.addColorStop(1, 'rgba(11,39,45,.72)');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, vw, vh);

    if (waterPattern) {
      const ox = (t * 4) % 360, oy = (t * 1.2) % 360;
      ctx.save();
      ctx.translate(ox - 360, oy - 360);
      ctx.fillStyle = waterPattern;
      ctx.fillRect(0, 0, vw + 720, vh + 720);
      ctx.restore();
    }

    // glints on open water
    ctx.save();
    for (let i = 0; i < 27; i++) {
      const h = G.hash(i, 4, 9);
      const x = h * vw + Math.sin(t * .25 + i) * 8;
      const y = G.hash(i, 9, 3) * vh;
      const a = .07 + .10 * (Math.sin(t * .8 + i * 1.7) * .5 + .5);
      ctx.strokeStyle = `rgba(189,228,216,${a})`;
      ctx.lineWidth = .8;
      ctx.beginPath();
      ctx.moveTo(x - 10, y);
      ctx.quadraticCurveTo(x, y - 2, x + 10, y);
      ctx.stroke();
    }
    ctx.restore();

    // soft mist bands at the top and far edges
    const mist = ctx.createLinearGradient(0, 0, 0, vh * .34);
    mist.addColorStop(0, 'rgba(186,206,181,.10)');
    mist.addColorStop(1, 'rgba(186,206,181,0)');
    ctx.fillStyle = mist;
    ctx.fillRect(0, 0, vw, vh * .34);
  }

  const GRASS = [
    [123, 154, 79], [132, 163, 86], [116, 146, 75], [140, 168, 92], [127, 158, 82]
  ];

  function drawTile(x, y, t) {
    const tile = G.terrainAt(x, y);
    if (!tile) return;
    const p = project(x, y);
    const s = G.camera.scale;
    const tw = G.TW * s, th = G.TH * s;
    const isWater = tile.kind === 'water';

    if (isWater) {
      diamond(p.x, p.y, tw, th, 0);
      const wg = ctx.createLinearGradient(p.x, p.y - th / 2, p.x, p.y + th / 2);
      wg.addColorStop(0, 'rgba(51,111,112,.94)');
      wg.addColorStop(.55, 'rgba(34,89,98,.96)');
      wg.addColorStop(1, 'rgba(25,72,83,.98)');
      ctx.fillStyle = wg;
      ctx.fill();
      ctx.strokeStyle = 'rgba(15,50,52,.42)';
      ctx.lineWidth = Math.max(.6, 1 * s);
      ctx.stroke();
      ctx.save();
      diamond(p.x, p.y, tw, th, 0);
      ctx.clip();
      for (let i = 0; i < 3; i++) {
        const u = G.hash(x, y, i + 70), v = G.hash(x, y, i + 80);
        const px = p.x + (u - v) * tw * .33;
        const py = p.y + (u + v - 1) * th * .34;
        const wob = Math.sin(t * 1.2 + i * 2 + x) * 2 * s;
        ctx.strokeStyle = `rgba(190,226,216,${.12 + .06 * i})`;
        ctx.lineWidth = Math.max(.6, 1 * s);
        ctx.beginPath();
        ctx.moveTo(px - 6 * s + wob, py);
        ctx.quadraticCurveTo(px + wob, py - 1.8 * s, px + 6 * s + wob, py);
        ctx.stroke();
      }
      ctx.restore();
      return;
    }

    // cliff faces
    const side = 14 * s;
    ctx.fillStyle = '#665538';
    ctx.beginPath();
    ctx.moveTo(p.x - tw / 2, p.y);
    ctx.lineTo(p.x, p.y + th / 2);
    ctx.lineTo(p.x, p.y + th / 2 + side);
    ctx.lineTo(p.x - tw / 2, p.y + side);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#4d402b';
    ctx.beginPath();
    ctx.moveTo(p.x, p.y + th / 2);
    ctx.lineTo(p.x + tw / 2, p.y);
    ctx.lineTo(p.x + tw / 2, p.y + side);
    ctx.lineTo(p.x, p.y + th / 2 + side);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(31,26,16,.26)';
    ctx.lineWidth = .7;
    ctx.beginPath();
    ctx.moveTo(p.x - tw / 2, p.y + side);
    ctx.lineTo(p.x, p.y + th / 2 + side);
    ctx.lineTo(p.x + tw / 2, p.y + side);
    ctx.stroke();

    const c = GRASS[(tile.variant + x + y) % GRASS.length];
    diamond(p.x, p.y, tw, th, 0);
    ctx.fillStyle = `rgb(${c[0]},${c[1]},${c[2]})`;
    ctx.fill();

    // subtle isometric light/shade
    ctx.save();
    diamond(p.x, p.y, tw, th, 0);
    ctx.clip();
    ctx.fillStyle = 'rgba(255,248,203,.055)';
    ctx.beginPath();
    ctx.moveTo(p.x, p.y - th / 2);
    ctx.lineTo(p.x - tw / 2, p.y);
    ctx.lineTo(p.x, p.y + th / 2);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(24,49,27,.045)';
    ctx.beginPath();
    ctx.moveTo(p.x, p.y - th / 2);
    ctx.lineTo(p.x + tw / 2, p.y);
    ctx.lineTo(p.x, p.y + th / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    ctx.strokeStyle = 'rgba(45,68,35,.30)';
    ctx.lineWidth = Math.max(.55, .8 * s);
    diamond(p.x, p.y, tw, th, 0);
    ctx.stroke();

    // blades and flowers
    const detail = tile.kind === 'rock' ? 1 : 4;
    for (let i = 0; i < detail; i++) {
      const u = G.hash(x, y, i + 11), v = G.hash(x, y, i + 21);
      const px = p.x + (u - v) * tw * .34;
      const py = p.y + (u + v - 1) * th * .34;
      const hh = (2 + G.hash(x, y, i + 31) * 3) * s;
      ctx.strokeStyle = `rgba(53,82,37,${.24 + .18 * G.hash(x, y, i + 41)})`;
      ctx.lineWidth = Math.max(.5, .8 * s);
      ctx.beginPath();
      ctx.moveTo(px, py);
      ctx.quadraticCurveTo(px - 1.4 * s, py - hh * .6, px - 2.4 * s, py - hh);
      ctx.moveTo(px, py);
      ctx.quadraticCurveTo(px + 1.4 * s, py - hh * .6, px + 2.2 * s, py - hh * .9);
      ctx.stroke();
    }

    for (let i = 0; i < 3; i++) {
      if (G.hash(x, y, i + 50) > .17) continue;
      const u = G.hash(x, y, i + 61), v = G.hash(x, y, i + 71);
      const px = p.x + (u - v) * tw * .27;
      const py = p.y + (u + v - 1) * th * .27;
      const colors = ['#e7c86e', '#e7b1a6', '#d4b1d1', '#f0dca0'];
      ctx.fillStyle = colors[i % colors.length];
      ctx.globalAlpha = .72;
      ctx.beginPath();
      ctx.arc(px, py, Math.max(.8, 1.2 * s), 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    // shoreline foam
    const south = G.terrainAt(x + 1, y), east = G.terrainAt(x, y + 1);
    if (!south || south.kind === 'water' || !east || east.kind === 'water') {
      ctx.strokeStyle = 'rgba(225,237,207,.33)';
      ctx.lineWidth = Math.max(.7, 1.2 * s);
      ctx.beginPath();
      if (!south || south.kind === 'water') {
        ctx.moveTo(p.x - tw / 2, p.y);
        ctx.lineTo(p.x, p.y + th / 2);
        ctx.lineTo(p.x, p.y + th / 2 + 2 * s);
      }
      if (!east || east.kind === 'water') {
        if (!south || south.kind === 'water') ctx.moveTo(p.x, p.y + th / 2 + 2 * s);
        else ctx.moveTo(p.x, p.y + th / 2);
        ctx.lineTo(p.x + tw / 2, p.y);
      }
      ctx.stroke();
    }
  }

  function drawRoads() {
    const s = G.camera.scale;
    const tw = G.TW * s, th = G.TH * s;
    const roads = G.state.buildings.filter(b => b.type === 'road');
    for (const r of roads) {
      const p = project(r.x, r.y);
      diamond(p.x, p.y, tw, th, 1);
      ctx.fillStyle = '#a99a7e';
      ctx.fill();
      diamond(p.x, p.y, tw, th, 2.5 * s);
      ctx.fillStyle = '#8e8069';
      ctx.fill();
      // cobbles
      ctx.save();
      diamond(p.x, p.y, tw, th, 1);
      ctx.clip();
      for (let i = 0; i < 8; i++) {
        const u = G.hash(r.x, r.y, i + 1), v = G.hash(r.x, r.y, i + 7);
        const px = p.x + (u - v) * tw * .38;
        const py = p.y + (u + v - 1) * th * .38;
        const rw = (2.4 + G.hash(r.x, r.y, i + 10) * 3.6) * s;
        const rh = rw * .44;
        ctx.beginPath();
        ctx.ellipse(px, py, rw, rh, 0, 0, Math.PI * 2);
        ctx.fillStyle = i % 3 === 0 ? 'rgba(184,169,139,.64)' : 'rgba(201,187,157,.52)';
        ctx.fill();
        ctx.strokeStyle = 'rgba(92,79,58,.28)';
        ctx.lineWidth = .6;
        ctx.stroke();
      }
      // gently worn centre
      ctx.strokeStyle = 'rgba(92,75,52,.17)';
      ctx.lineWidth = Math.max(.7, 1 * s);
      ctx.beginPath();
      ctx.moveTo(p.x - tw * .22, p.y + th * .05);
      ctx.lineTo(p.x + tw * .18, p.y + th * .23);
      ctx.stroke();
      ctx.restore();
    }
  }

  function drawSceneryShadow(prop, p, scale, size) {
    ctx.save();
    ctx.globalAlpha = .23;
    ctx.fillStyle = '#162b17';
    ctx.beginPath();
    ctx.ellipse(p.x + 3 * scale, p.y + 2 * scale, size * .34, size * .12, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  const sceneryBase = { oak1: 84, oak2: 88, pine1: 73, pine2: 66, poplar: 55, bush: 58, rock: 80, flowers: 56, fence: 72, boat: 75 };

  function drawScenery(prop, t) {
    if (prop.decor && G.buildingAt(prop.x, prop.y)) return;
    if (prop.water && G.buildingAt(prop.x, prop.y)) return;
    const img = images[prop.sprite];
    if (!img) return;
    const p = project(prop.x + (prop.dx || 0), prop.y + (prop.dy || 0));
    const s = G.camera.scale;
    const base = sceneryBase[prop.sprite] || 70;
    const w = base * prop.scale * s;
    const h = w * (img.height / img.width);
    const bottom = p.y + G.TH * .33 * s + (prop.sprite === 'bush' ? 4 * s : 0);
    drawSceneryShadow(prop, p, s, w);
    // gentle breezy sway
    const sway = Math.sin(t * .7 + prop.x * .9 + prop.y) * (.7 + .6 * prop.scale) * s;
    ctx.save();
    if (prop.sprite !== 'rock' && prop.sprite !== 'fence' && prop.sprite !== 'flowers') {
      ctx.translate(p.x, bottom);
      ctx.transform(1, 0, sway / (w * 6), 1, 0, 0);
      ctx.drawImage(img, -w / 2, -h, w, h);
    } else {
      ctx.drawImage(img, p.x - w / 2, bottom - h, w, h);
    }
    ctx.restore();
  }

  function spriteFor(b) {
    if (b.type === 'house') return 'house' + (((b.variant || 1) - 1) % 3 + 1);
    return b.type;
  }

  function drawBuilding(b, t) {
    const def = G.BUILDINGS[b.type];
    if (!def) return;
    const key = spriteFor(b);
    const img = images[key];
    const p = project(b.x, b.y);
    const s = G.camera.scale;
    const artW = (def.art?.w || 150) * s;
    const bottom = p.y + G.TH * .36 * s + (def.art?.dy || 0) * s;
    let w = artW;
    let h = img ? artW * (img.height / img.width) : artW * .9;

    ctx.save();
    ctx.globalAlpha = .26;
    ctx.fillStyle = '#172b18';
    ctx.beginPath();
    ctx.ellipse(p.x + 2 * s, p.y + G.TH * .18 * s, artW * .33, artW * .1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    if (img) ctx.drawImage(img, p.x - w / 2, bottom - h, w, h);
    else {
      // graceful fallback while art loads
      const g = ctx.createLinearGradient(p.x, bottom - h, p.x, bottom);
      g.addColorStop(0, '#c9b18a'); g.addColorStop(1, '#7f6242');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(p.x, bottom - h);
      ctx.lineTo(p.x + w * .4, bottom - h * .45);
      ctx.lineTo(p.x + w * .4, bottom);
      ctx.lineTo(p.x - w * .4, bottom);
      ctx.lineTo(p.x - w * .4, bottom - h * .45);
      ctx.closePath();
      ctx.fill();
    }

    const hit = { b, x: p.x - w / 2, y: bottom - h, w, h, depth: b.x + b.y };
    hitObjects.push(hit);

    if (b.level > 1) drawLevelPips(b, p, bottom - h, artW, s);
    return { p, w, h, bottom };
  }

  function drawLevelPips(b, p, top, w, s) {
    const n = b.level - 1;
    const y = top + 11 * s;
    for (let i = 0; i < n; i++) {
      const x = p.x + (i - (n - 1) / 2) * 9 * s;
      ctx.save();
      ctx.translate(x, y);
      ctx.fillStyle = '#e5c269';
      ctx.strokeStyle = 'rgba(83,57,22,.8)';
      ctx.lineWidth = .8 * s;
      ctx.beginPath();
      for (let k = 0; k < 5; k++) {
        const a = -Math.PI / 2 + k * Math.PI * 2 / 5;
        const r = 3.2 * s;
        ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
      }
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }
  }

  function sceneryDepth(prop) {
    return prop.x + (prop.dx || 0) + prop.y + (prop.dy || 0) + (prop.sort || 0) * .12;
  }

  function drawPondReeds(t) {
    // small animated glints on the pond
    for (const [x, y] of [[2, 8], [3, 8], [2, 9], [3, 9]]) {
      const p = project(x, y);
      const s = G.camera.scale;
      for (let i = 0; i < 3; i++) {
        const px = p.x + (G.hash(x, y, i) - .5) * G.TW * .55 * s;
        const py = p.y + (G.hash(x, y, i + 10) - .5) * G.TH * .55 * s;
        ctx.strokeStyle = `rgba(208,235,220,${.12 + .07 * Math.sin(t + i)})`;
        ctx.lineWidth = .8 * s;
        ctx.beginPath();
        ctx.moveTo(px - 5 * s, py);
        ctx.quadraticCurveTo(px, py - 1.5 * s, px + 5 * s, py);
        ctx.stroke();
      }
    }
  }

  function drawCloudShadows(t) {
    const s = G.camera.scale;
    ctx.save();
    for (let i = 0; i < 2; i++) {
      const x = ((t * (6 + i * 3) + i * 620) % (vw + 800)) - 240;
      const y = vh * (.28 + i * .28);
      const r = 220 + i * 90;
      const g = ctx.createRadialGradient(x, y, 5, x, y, r);
      g.addColorStop(0, 'rgba(17,41,24,.12)');
      g.addColorStop(.7, 'rgba(17,41,24,.055)');
      g.addColorStop(1, 'rgba(17,41,24,0)');
      ctx.fillStyle = g;
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(1.7, .58);
      ctx.translate(-x, -y);
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  function drawBirds(t) {
    ctx.save();
    ctx.strokeStyle = 'rgba(28,43,30,.48)';
    ctx.lineWidth = 1.1;
    for (let i = 0; i < 4; i++) {
      const speed = 7 + i * 2.6;
      const x = ((t * speed + i * 340) % (vw + 280)) - 140;
      const y = 118 + i * 27 + Math.sin(t * .6 + i * 2) * 6;
      const flap = Math.sin(t * 4 + i) * 2.4;
      ctx.beginPath();
      ctx.moveTo(x - 6, y + flap);
      ctx.quadraticCurveTo(x - 2, y - 2, x, y);
      ctx.quadraticCurveTo(x + 2, y - 2, x + 6, y + flap);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawMotes(t) {
    ctx.save();
    for (let i = 0; i < 22; i++) {
      const h = G.hash(i, 3, 5), v = G.hash(i, 8, 2);
      const x = h * vw + Math.sin(t * .18 + i) * 20;
      const y = vh * .28 + v * vh * .48 + Math.cos(t * .22 + i * 1.3) * 13;
      const a = .08 + .16 * (Math.sin(t * .9 + i * 2.2) * .5 + .5);
      ctx.fillStyle = `rgba(245,220,153,${a})`;
      ctx.beginPath();
      ctx.arc(x, y, .8 + h * 1.2, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  function drawSelection(t) {
    if (!G.ui.selected) return;
    const b = G.state.buildings.find(x => x.id === G.ui.selected);
    if (!b) return;
    const p = project(b.x, b.y);
    const s = G.camera.scale;
    const tw = G.TW * s, th = G.TH * s;
    const pulse = .55 + .25 * Math.sin(t * 4);
    ctx.save();
    diamond(p.x, p.y, tw + 7 * s, th + 4 * s, 0);
    ctx.strokeStyle = `rgba(242,211,133,${pulse})`;
    ctx.lineWidth = 2 * s;
    ctx.stroke();
    ctx.strokeStyle = 'rgba(56,36,16,.5)';
    ctx.lineWidth = .8 * s;
    diamond(p.x, p.y, tw + 2 * s, th + 1 * s, 0);
    ctx.stroke();
    // corner studs
    const points = [[p.x, p.y - th / 2], [p.x + tw / 2, p.y], [p.x, p.y + th / 2], [p.x - tw / 2, p.y]];
    for (const pt of points) {
      ctx.beginPath();
      ctx.arc(pt.x, pt.y, 2.2 * s, 0, Math.PI * 2);
      ctx.fillStyle = '#efd085';
      ctx.fill();
    }
    ctx.restore();
  }

  function drawHoverAndGhost(t) {
    const hover = G.ui.hover;
    if (!hover || hover.x < 0 || hover.y < 0 || hover.x >= G.MAP_W || hover.y >= G.MAP_H) return;
    const p = project(hover.x, hover.y);
    const s = G.camera.scale;
    const tw = G.TW * s, th = G.TH * s;

    if (G.ui.demolish) {
      const b = G.buildingAt(hover.x, hover.y);
      if (b) {
        diamond(p.x, p.y, tw, th, 0);
        ctx.fillStyle = 'rgba(166,58,42,.24)';
        ctx.fill();
        ctx.strokeStyle = 'rgba(228,126,103,.9)';
        ctx.lineWidth = 2 * s;
        ctx.stroke();
      }
      return;
    }

    if (!G.ui.buildType) {
      diamond(p.x, p.y, tw, th, 0);
      ctx.strokeStyle = 'rgba(242,215,147,.35)';
      ctx.lineWidth = 1 * s;
      ctx.stroke();
      return;
    }

    const def = G.BUILDINGS[G.ui.buildType];
    if (!def) return;
    const check = G.canPlace(G.ui.buildType, hover.x, hover.y, true);
    const ok = check.ok;
    const img = images[spriteFor({ type: G.ui.buildType, variant: 1 })];
    diamond(p.x, p.y, tw, th, 0);
    ctx.fillStyle = ok ? 'rgba(153,194,101,.23)' : 'rgba(167,72,54,.25)';
    ctx.fill();
    ctx.strokeStyle = ok ? 'rgba(214,236,161,.9)' : 'rgba(234,130,107,.9)';
    ctx.lineWidth = 1.6 * s;
    ctx.stroke();

    if (G.ui.buildType !== 'road' && img) {
      const artW = (def.art?.w || 150) * s;
      const bottom = p.y + G.TH * .36 * s + (def.art?.dy || 0) * s;
      const h = artW * (img.height / img.width);
      ctx.save();
      ctx.globalAlpha = .5;
      if (!ok) {
        ctx.drawImage(img, p.x - artW / 2, bottom - h, artW, h);
        ctx.globalCompositeOperation = 'source-atop';
        ctx.fillStyle = 'rgba(150,40,24,.33)';
        ctx.fillRect(p.x - artW / 2, bottom - h, artW, h);
      } else {
        ctx.drawImage(img, p.x - artW / 2, bottom - h, artW, h);
      }
      ctx.restore();
    } else if (G.ui.buildType === 'road') {
      diamond(p.x, p.y, tw, th, 2);
      ctx.fillStyle = ok ? 'rgba(173,154,121,.78)' : 'rgba(138,66,49,.73)';
      ctx.fill();
    }
  }

  function drawBuildMarkers(t) {
    if (!G.ui.buildType) return;
    const s = G.camera.scale;
    const pulse = .35 + .2 * Math.sin(t * 2.8);
    for (let y = 0; y < G.MAP_H; y++) {
      for (let x = 0; x < G.MAP_W; x++) {
        const tile = G.terrainAt(x, y);
        if (!tile || tile.kind !== 'grass' || G.buildingAt(x, y)) continue;
        const p = project(x, y);
        ctx.save();
        ctx.globalAlpha = pulse;
        ctx.fillStyle = '#f0d48a';
        ctx.beginPath();
        ctx.moveTo(p.x, p.y - 2.2 * s);
        ctx.lineTo(p.x + 2.2 * s, p.y);
        ctx.lineTo(p.x, p.y + 2.2 * s);
        ctx.lineTo(p.x - 2.2 * s, p.y);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }
    }
  }

  function drawDemolishMarks(t) {
    if (!G.ui.demolish) return;
    const s = G.camera.scale;
    for (const b of G.state.buildings) {
      if (b.type === 'keep') continue;
      const p = project(b.x, b.y);
      ctx.save();
      ctx.globalAlpha = .3 + .15 * Math.sin(t * 3);
      ctx.strokeStyle = '#dc8a70';
      ctx.lineWidth = 1.2 * s;
      const r = 5 * s;
      ctx.beginPath();
      ctx.moveTo(p.x - r, p.y - r); ctx.lineTo(p.x + r, p.y + r);
      ctx.moveTo(p.x + r, p.y - r); ctx.lineTo(p.x - r, p.y + r);
      ctx.stroke();
      ctx.restore();
    }
  }

  function updateParticles(dt) {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += p.gravity * dt;
      if (p.life <= 0) particles.splice(i, 1);
    }
  }

  function drawParticles() {
    for (const p of particles) {
      const a = Math.max(0, p.life / p.maxLife);
      ctx.globalAlpha = a * p.alpha;
      ctx.fillStyle = p.color;
      if (p.kind === 'spark') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        ctx.fillRect(-p.size * .5, -p.size * 1.4, p.size, p.size * 2.8);
        ctx.restore();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (1.2 - a * .2), 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }

  function spawnFx(detail) {
    const s = G.camera.scale;
    const kind = detail.kind;
    const tile = detail.x != null ? project(detail.x, detail.y) : project(6, 4);
    if (kind === 'build' || kind === 'upgrade' || kind === 'demolish') {
      const colors = kind === 'demolish' ? ['#b58155', '#8b6341', '#d2b17e'] : ['#e3c27b', '#c9a363', '#f0d995', '#b9a07b'];
      for (let i = 0; i < 20; i++) {
        const a = Math.random() * Math.PI * 2;
        const sp = (20 + Math.random() * 70) * s;
        particles.push({
          kind: 'dust', x: tile.x + (Math.random() - .5) * 45 * s, y: tile.y + (Math.random() - .2) * 20 * s,
          vx: Math.cos(a) * sp, vy: -Math.abs(Math.sin(a)) * sp * .7 - 15 * s,
          gravity: 95 * s, life: .65 + Math.random() * .65, maxLife: 1.3,
          size: (1.5 + Math.random() * 3.5) * s, color: colors[i % colors.length], alpha: .5
        });
      }
    }
    if (kind === 'levelup' || kind === 'quest') {
      for (let i = 0; i < 34; i++) {
        const a = Math.random() * Math.PI * 2;
        particles.push({
          kind: 'spark', x: tile.x + (Math.random() - .5) * 100 * s, y: tile.y - 30 * s,
          vx: Math.cos(a) * (20 + Math.random() * 80) * s, vy: -(30 + Math.random() * 90) * s,
          gravity: 40 * s, life: .9 + Math.random() * .9, maxLife: 1.8,
          size: (1.3 + Math.random() * 2) * s, color: i % 3 ? '#edd18a' : '#fff1c1', alpha: .8, rot: Math.random() * 6
        });
      }
    }
    if (kind === 'growth' || kind === 'festival') {
      for (let i = 0; i < 14; i++) {
        particles.push({
          kind: 'spark', x: tile.x + (Math.random() - .5) * 150 * s, y: tile.y - 40 * s,
          vx: (Math.random() - .5) * 20 * s, vy: -(20 + Math.random() * 45) * s,
          gravity: 8 * s, life: 1.1 + Math.random(), maxLife: 2.1,
          size: (1.1 + Math.random() * 1.6) * s, color: i % 2 ? '#f3da94' : '#d7b2d0', alpha: .8, rot: 0
        });
      }
    }
  }
  window.addEventListener('kb:fx', e => spawnFx(e.detail || {}));

  function drawSmoke(t) {
    if (!G.state) return;
    const s = G.camera.scale;
    for (const b of G.state.buildings) {
      if (!['house', 'tavern', 'factory', 'keep', 'lumber'].includes(b.type)) continue;
      if (b.type === 'lumber') continue;
      const def = G.BUILDINGS[b.type];
      const p = project(b.x, b.y);
      const artW = (def.art?.w || 150) * s;
      const bottom = p.y + G.TH * .36 * s + (def.art?.dy || 0) * s;
      const top = bottom - artW;
      const offset = b.type === 'keep' ? artW * .1 : (b.type === 'house' ? artW * .18 : -artW * .12);
      const baseX = p.x + offset;
      const baseY = b.type === 'keep' ? top + artW * .30 : top + artW * .43;
      for (let i = 0; i < 3; i++) {
        const age = ((t * .17 + i / 3 + G.hash(b.x, b.y, i) * .8) % 1);
        const y = baseY - age * 42 * s;
        const x = baseX + Math.sin(age * 6 + i * 2.2) * 5 * s + age * 7 * s;
        const a = .14 * (1 - age);
        ctx.fillStyle = `rgba(221,218,203,${a})`;
        ctx.beginPath();
        ctx.arc(x, y, (1.4 + age * 4.4) * s, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  function render(t) {
    const dt = lastFrame ? Math.min(.05, t - lastFrame) : .016;
    lastFrame = t;
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.clearRect(0, 0, vw, vh);
    drawWater(t);

    // island shadow
    ctx.save();
    ctx.globalAlpha = .14;
    ctx.fillStyle = '#06120c';
    for (let y = 0; y < G.MAP_H; y++) {
      for (let x = 0; x < G.MAP_W; x++) {
        const tile = G.terrainAt(x, y);
        if (!tile || tile.kind === 'water') continue;
        const p = project(x, y);
        diamond(p.x, p.y + 16 * G.camera.scale, G.TW * G.camera.scale, G.TH * G.camera.scale, 0);
        ctx.fill();
      }
    }
    ctx.restore();

    for (let sum = 0; sum <= G.MAP_W + G.MAP_H - 2; sum++) {
      for (let x = 0; x < G.MAP_W; x++) {
        const y = sum - x;
        if (y >= 0 && y < G.MAP_H) drawTile(x, y, t);
      }
    }

    drawRoads();
    drawPondReeds(t);
    drawCloudShadows(t);
    drawBuildMarkers(t);
    drawDemolishMarks(t);

    hitObjects.length = 0;
    const objs = [];
    for (const b of G.state.buildings) {
      if (b.type === 'road') continue;
      objs.push({ kind: 'building', b, depth: b.x + b.y + .01 });
    }
    for (const prop of G.scenery) {
      if (prop.decor && G.buildingAt(prop.x, prop.y)) continue;
      objs.push({ kind: 'scenery', prop, depth: sceneryDepth(prop) });
    }
    objs.sort((a, b) => a.depth - b.depth || (a.b?.x || 0) - (b.b?.x || 0));

    for (const o of objs) {
      if (o.kind === 'building') drawBuilding(o.b, t);
      else drawScenery(o.prop, t);
    }

    drawSmoke(t);
    drawSelection(t);
    drawHoverAndGhost(t);
    drawMotes(t);
    drawBirds(t);
    updateParticles(dt);
    drawParticles();

    requestAnimationFrame(render);
  }

  // ---------- interaction ----------
  function setModeUI() {
    const dock = document.getElementById('buildDock');
    const modeText = document.getElementById('modeText');
    const hint = document.getElementById('mapHint');
    const buildType = G.ui.buildType;
    const name = buildType ? G.BUILDINGS[buildType].name : '';
    dock.classList.toggle('building', !!(buildType || G.ui.demolish));
    canvas.classList.toggle('build-mode', !!buildType);
    canvas.classList.toggle('pointer', !buildType && !G.ui.demolish);
    if (buildType) {
      modeText.textContent = `Placing ${name} · tap a plot`;
      hint.innerHTML = `<span class="hint-key">✦</span><span>Tap a grassy plot to place ${name}. <b>Esc</b> to stop.</span>`;
      hint.classList.remove('hidden');
    } else if (G.ui.demolish) {
      modeText.textContent = 'Bulldoze selected';
      hint.innerHTML = `<span class="hint-key">✦</span><span>Tap a structure to salvage it. <b>Esc</b> to stop.</span>`;
      hint.classList.remove('hidden');
    } else {
      modeText.textContent = G.ui.selected ? 'Inspecting the realm' : 'Village view';
      hint.innerHTML = `<span class="hint-key">✦</span><span>Choose a building below, then tap a grassy plot.</span>`;
      hint.classList.remove('hidden');
    }
    window.dispatchEvent(new CustomEvent('kb:mode', { detail: { buildType, demolish: G.ui.demolish, selected: G.ui.selected } }));
  }

  G.setBuildMode = function (type) {
    if (!type) { G.cancelBuild(); return; }
    G.ui.buildType = type;
    G.ui.demolish = false;
    G.ui.selected = null;
    setModeUI();
    if (G.refreshUI) G.refreshUI();
  };

  G.setDemolishMode = function () {
    G.ui.demolish = !G.ui.demolish;
    G.ui.buildType = null;
    G.ui.selected = null;
    setModeUI();
    if (G.refreshUI) G.refreshUI();
  };

  G.cancelBuild = function () {
    G.ui.buildType = null;
    G.ui.demolish = false;
    G.ui.hover = null;
    setModeUI();
    if (G.refreshUI) G.refreshUI();
  };

  G.clearSelection = function () {
    G.ui.selected = null;
    G.ui.buildType = null;
    G.ui.demolish = false;
    setModeUI();
    window.dispatchEvent(new CustomEvent('kb:selection', { detail: null }));
    if (G.refreshUI) G.refreshUI();
  };

  G.selectBuilding = function (id) {
    G.ui.selected = id;
    G.ui.buildType = null;
    G.ui.demolish = false;
    setModeUI();
    window.dispatchEvent(new CustomEvent('kb:selection', { detail: { id } }));
    if (G.refreshUI) G.refreshUI();
  };

  function hitAt(sx, sy) {
    for (let i = hitObjects.length - 1; i >= 0; i--) {
      const h = hitObjects[i];
      if (sx >= h.x && sx <= h.x + h.w && sy >= h.y && sy <= h.y + h.h) return h;
    }
    return null;
  }

  function handleMapClick(sx, sy) {
    const hit = hitAt(sx, sy);
    const tile = G.screenToTile(sx, sy);

    if (G.ui.buildType) {
      const target = hit ? { x: hit.b.x, y: hit.b.y } : tile;
      if (G.buildingAt(target.x, target.y)) {
        G.toast('Plot occupied', 'Choose an empty grassy plot for your new building.', 'bad', '✕');
        return;
      }
      const res = G.place(G.ui.buildType, target.x, target.y);
      if (res.ok) {
        const def = G.BUILDINGS[G.ui.buildType];
        G.toast(`${def.name} raised`, `A fine addition to Valewood. +${def.xp} renown.`, 'good', '⚒');
        G.camera.panX += 0;
        if (G.refreshUI) G.refreshUI(true);
      } else if (res.missing) {
        const chip = document.querySelector(`.resource-chip[data-res="${res.missing}"]`);
        if (chip) { chip.classList.remove('pulse'); void chip.offsetWidth; chip.classList.add('pulse'); }
      }
      return;
    }

    if (G.ui.demolish) {
      const b = hit?.b || G.buildingAt(tile.x, tile.y);
      if (!b) { G.toast('Nothing to remove', 'Tap a building or road to salvage it.', '', '⌫'); return; }
      G.demolish(b.id);
      G.ui.selected = null;
      if (G.refreshUI) G.refreshUI(true);
      return;
    }

    if (hit) {
      G.selectBuilding(hit.b.id);
      return;
    }
    const b = G.buildingAt(tile.x, tile.y);
    if (b) {
      G.selectBuilding(b.id);
      return;
    }
    if (G.terrainAt(tile.x, tile.y) && G.terrainAt(tile.x, tile.y).kind === 'water') {
      G.toast('The river', 'Boats and bridges will come another day.', '', '≈');
      return;
    }
    G.clearSelection();
  }

  function pointerPos(e) {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  function beginPinch() {
    const arr = Array.from(pointers.values());
    if (arr.length < 2) return;
    const dx = arr[0].x - arr[1].x, dy = arr[0].y - arr[1].y;
    pinch = { dist: Math.max(20, Math.hypot(dx, dy)), zoom: G.camera.userZoom };
    G.ui.dragging = true;
    suppressTap = true;
    drag = null;
  }

  canvas.addEventListener('pointerdown', e => {
    if (e.button === 2) { G.cancelBuild(); return; }
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const pos = pointerPos(e);
    pointers.set(e.pointerId, { x: pos.x, y: pos.y, startX: pos.x, startY: pos.y, id: e.pointerId });
    try { canvas.setPointerCapture(e.pointerId); } catch { /* noop */ }
    if (pointers.size === 2) beginPinch();
    else if (pointers.size === 1) {
      drag = { id: e.pointerId, x: pos.x, y: pos.y, startX: pos.x, startY: pos.y, moved: false, t: performance.now() };
      G.ui.hover = G.screenToTile(pos.x, pos.y);
    }
  });

  canvas.addEventListener('pointermove', e => {
    const pos = pointerPos(e);
    if (pointers.has(e.pointerId)) pointers.set(e.pointerId, { ...pointers.get(e.pointerId), x: pos.x, y: pos.y });

    if (pointers.size === 2 && pinch) {
      const arr = Array.from(pointers.values());
      const dist = Math.hypot(arr[0].x - arr[1].x, arr[0].y - arr[1].y);
      const z = G.clamp(pinch.zoom * (dist / pinch.dist), G.camera.minZoom, G.camera.maxZoom);
      G.camera.userZoom = z;
      updateCamera();
      clampPan();
      G.ui.dragging = true;
      return;
    }

    if (drag && pointers.size === 1 && e.pointerId === drag.id) {
      const dx = pos.x - drag.x, dy = pos.y - drag.y;
      if (Math.abs(pos.x - drag.startX) + Math.abs(pos.y - drag.startY) > 6) {
        drag.moved = true;
        G.ui.dragging = true;
      }
      if (drag.moved) {
        G.camera.panX += dx;
        G.camera.panY += dy;
        clampPan();
        updateCamera();
      }
      drag.x = pos.x; drag.y = pos.y;
      G.ui.hover = null;
      return;
    }

    if (e.pointerType === 'mouse') {
      const tile = G.screenToTile(pos.x, pos.y);
      G.ui.hover = tile;
      canvas.classList.toggle('pointer', !G.ui.buildType && !G.ui.demolish && !!G.buildingAt(tile.x, tile.y));
    }
  });

  function endPointer(e, cancelled = false) {
    const wasDrag = drag?.moved;
    const wasPinch = !!pinch;
    const pos = pointerPos(e);
    const onePointer = pointers.size === 1;
    if (!cancelled && onePointer && !wasDrag && !wasPinch && !suppressTap && drag && e.pointerId === drag.id) {
      handleMapClick(pos.x, pos.y);
    }
    pointers.delete(e.pointerId);
    if (pointers.size < 2) pinch = null;
    if (pointers.size === 0) {
      suppressTap = false;
      drag = null;
      G.ui.dragging = false;
    }
  }

  canvas.addEventListener('pointerup', e => endPointer(e));
  canvas.addEventListener('pointercancel', e => endPointer(e, true));
  canvas.addEventListener('contextmenu', e => e.preventDefault());

  canvas.addEventListener('wheel', e => {
    e.preventDefault();
    const pos = pointerPos(e);
    const oldScale = G.camera.scale;
    const wx = (pos.x - G.camera.ox) / oldScale;
    const wy = (pos.y - G.camera.oy) / oldScale;
    const factor = Math.exp(-e.deltaY * .0012);
    G.camera.userZoom = G.clamp(G.camera.userZoom * factor, G.camera.minZoom, G.camera.maxZoom);
    const oldPanX = G.camera.panX, oldPanY = G.camera.panY;
    updateCamera();
    const newScale = G.camera.scale;
    G.camera.panX = pos.x - wx * newScale - (vw / 2 - 75 * newScale);
    G.camera.panY = pos.y - wy * newScale - ((vw < 760 ? vh * .475 : vh * .5) - 287.5 * newScale);
    clampPan();
    updateCamera();
  }, { passive: false });

  window.addEventListener('resize', () => {
    G.resizeWorld();
  });

  G.startWorld = function () {
    G.resizeWorld();
    requestAnimationFrame(t => {
      lastFrame = t;
      requestAnimationFrame(render);
    });
  };

  G.setModeUI = setModeUI;
})();

/* Kingdom Builder — interface, onboarding, audio and game loop. */
(function () {
  'use strict';
  const G = window.KBG;
  const KB = window.KBArt;
  const $ = sel => document.querySelector(sel);
  const $$ = sel => Array.from(document.querySelectorAll(sel));

  let lastEco = null;
  let cardsSignature = '';
  let lastSheetHTML = '';
  let lastQuestsHTML = '';
  let lastLedgerHTML = '';
  let audioCtx = null;
  let lastTick = performance.now();
  let booted = false;
  let modalKind = null;

  const RES_LABEL = { wood: 'Wood', stone: 'Stone', food: 'Food', gold: 'Gold' };

  // ---------- sound ----------
  function ensureAudio() {
    if (!G.state?.soundOn) return null;
    if (!audioCtx) {
      try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch { return null; }
    }
    if (audioCtx.state === 'suspended') audioCtx.resume().catch(() => {});
    return audioCtx;
  }

  function tone(freq, dur, type = 'sine', volume = .025, delay = 0) {
    const ac = ensureAudio();
    if (!ac) return;
    const t0 = ac.currentTime + delay;
    const osc = ac.createOscillator();
    const gain = ac.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(volume, t0 + .012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain).connect(ac.destination);
    osc.start(t0);
    osc.stop(t0 + dur + .03);
  }

  function playFx(kind) {
    if (!G.state?.soundOn) return;
    if (kind === 'build') {
      tone(196, .10, 'triangle', .035);
      tone(293.7, .16, 'triangle', .028, .06);
      tone(392, .26, 'sine', .018, .12);
    } else if (kind === 'upgrade') {
      tone(261.6, .1, 'triangle', .03);
      tone(392, .14, 'triangle', .025, .07);
      tone(523.3, .3, 'sine', .022, .14);
    } else if (kind === 'levelup' || kind === 'quest') {
      [392, 493.9, 587.3, 784].forEach((f, i) => tone(f, .32, 'sine', .025, i * .09));
    } else if (kind === 'growth') {
      tone(523.3, .12, 'sine', .018);
      tone(659.3, .18, 'sine', .014, .07);
    } else if (kind === 'demolish') {
      tone(130.8, .2, 'sawtooth', .018);
      tone(98, .25, 'triangle', .02, .08);
    } else if (kind === 'festival') {
      [523.3, 659.3, 784, 1046.5].forEach((f, i) => tone(f, .4, 'triangle', .022, i * .07));
    } else if (kind === 'tax') {
      tone(330, .08, 'triangle', .018);
      tone(440, .1, 'triangle', .016, .06);
    }
  }

  // ---------- toasts ----------
  function toast(title, msg, kind = '', icon = '✦') {
    const stack = $('#toastStack');
    const el = document.createElement('div');
    el.className = 'toast ' + kind;
    el.innerHTML = `<span class="toast-icon">${icon}</span><div><strong>${title}</strong>${msg ? `<small>${msg}</small>` : ''}</div>`;
    stack.appendChild(el);
    while (stack.children.length > 4) stack.firstElementChild.remove();
    setTimeout(() => {
      el.classList.add('leaving');
      setTimeout(() => el.remove(), 320);
    }, kind === 'bad' ? 2800 : 3600);
  }
  window.addEventListener('kb:toast', e => {
    const d = e.detail || {};
    toast(d.title || '', d.msg || '', d.kind || '', d.icon || '✦');
  });

  window.addEventListener('kb:fx', e => playFx((e.detail || {}).kind));

  // ---------- resource bar ----------
  function makeResourceBar() {
    const bar = $('#resourceBar');
    bar.innerHTML = '';
    const order = [
      ['wood', 'Wood'], ['stone', 'Stone'], ['food', 'Food'], ['gold', 'Gold'],
      ['pop', 'People'], ['happy', 'Contentment']
    ];
    for (const [key, label] of order) {
      const chip = document.createElement('div');
      chip.className = 'resource-chip';
      chip.dataset.res = key;
      chip.title = label;
      const icon = key === 'pop' ? KB.resIcons.pop : key === 'happy' ? KB.resIcons.happy : KB.resIcons[key];
      chip.innerHTML = `
        <div class="resource-icon">${icon}</div>
        <div class="resource-meta">
          <span class="resource-value" id="res-${key}">—</span>
          <span class="resource-rate" id="rate-${key}">—</span>
        </div>`;
      bar.appendChild(chip);
    }
  }

  function flashResource(res) {
    const chip = document.querySelector(`.resource-chip[data-res="${res}"]`);
    if (!chip) return;
    chip.classList.remove('pulse');
    void chip.offsetWidth;
    chip.classList.add('pulse');
  }

  // ---------- HUD refresh ----------
  function updateResources() {
    const s = G.state;
    for (const key of G.RESOURCES) {
      const value = $('#res-' + key);
      if (value) value.textContent = G.fmt(s.resources[key]);
      const rate = $('#rate-' + key);
      if (rate) {
        rate.textContent = G.perMin(lastEco.net[key]) + '/m';
