    $('#xpFill').style.width = prog.pct + '%';
    $('#xpText').textContent = prog.text;
    $('#nextLevelText').textContent = prog.next;
    $('#dayLabel').textContent = `Day ${G.day(s)}`;
    $('#seasonLabel').textContent = G.season(s);
