688:   function updateParticles(dt) {
689:     for (let i = particles.length - 1; i >= 0; i--) {
690:       const p = particles[i];
691:       p.life -= dt;
692:       p.x += p.vx * dt;
693:       p.y += p.vy * dt;
694:       p.vy += p.gravity * dt;
695:       if (p.life <= 0) particles.splice(i, 1);
696:     }
697:   }
