699:   function drawParticles() {
700:     for (const p of particles) {
701:       const a = Math.max(0, p.life / p.maxLife);
702:       ctx.globalAlpha = a * p.alpha;
703:       ctx.fillStyle = p.color;
704:       if (p.kind === 'spark') {
705:         ctx.save();
706:         ctx.translate(p.x, p.y);
707:         ctx.rotate(p.rot || 0);
708:         ctx.fillRect(-p.size * .5, -p.size * 1.4, p.size, p.size * 2.8);
709:         ctx.restore();
710:       } else {
711:         ctx.beginPath();
712:         ctx.arc(p.x, p.y, p.size * (1.2 - a * .2), 0, Math.PI * 2);
713:         ctx.fill();
714:       }
715:     }
716:     ctx.globalAlpha = 1;
717:   }
