751:           vx: (Math.random() - .5) * 20 * s, vy: -(20 + Math.random() * 45) * s,
752:           gravity: 8 * s, life: 1.1 + Math.random(), maxLife: 2.1,
753:           size: (1.1 + Math.random() * 1.6) * s, color: i % 2 ? '#f3da94' : '#d7b2d0', alpha: .8, rot: 0
