760:   function drawSmoke(t) {
761:     if (!G.state) return;
762:     const s = G.camera.scale;
763:     for (const b of G.state.buildings) {
764:       if (!['house', 'tavern', 'factory', 'keep', 'lumber'].includes(b.type)) continue;
765:       if (b.type === 'lumber') continue;
766:       const def = G.BUILDINGS[b.type];
767:       const p = project(b.x, b.y);
768:       const artW = (def.art?.w || 150) * s;
769:       const bottom = p.y + G.TH * .36 * s + (def.art?.dy || 0) * s;
770:       const top = bottom - artW;
771:       const offset = b.type === 'keep' ? artW * .1 : (b.type === 'house' ? artW * .18 : -artW * .12);
772:       const baseX = p.x + offset;
773:       const baseY = b.type === 'keep' ? top + artW * .30 : top + artW * .43;
774:       for (let i = 0; i < 3; i++) {
775:         const age = ((t * .17 + i / 3 + G.hash(b.x, b.y, i) * .8) % 1);
776:         const y = baseY - age * 42 * s;
777:         const x = baseX + Math.sin(age * 6 + i * 2.2) * 5 * s + age * 7 * s;
778:         const a = .14 * (1 - age);
779:         ctx.fillStyle = `rgba(221,218,203,${a})`;
780:         ctx.beginPath();
781:         ctx.arc(x, y, (1.4 + age * 4.4) * s, 0, Math.PI * 2);
782:         ctx.fill();
783:       }
784:     }
785:   }
