787:   function render(t) {
788:     const dt = lastFrame ? Math.min(.05, t - lastFrame) : .016;
789:     lastFrame = t;
790:     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
791:     ctx.clearRect(0, 0, vw, vh);
792:     drawWater(t);
793: 
794:     // island shadow
795:     ctx.save();
796:     ctx.globalAlpha = .14;
797:     ctx.fillStyle = '#06120c';
798:     for (let y = 0; y < G.MAP_H; y++) {
799:       for (let x = 0; x < G.MAP_W; x++) {
800:         const tile = G.terrainAt(x, y);
801:         if (!tile || tile.kind === 'water') continue;
802:         const p = project(x, y);
803:         diamond(p.x, p.y + 16 * G.camera.scale, G.TW * G.camera.scale, G.TH * G.camera.scale, 0);
804:         ctx.fill();
805:       }
806:     }
807:     ctx.restore();
808: 
809:     for (let sum = 0; sum <= G.MAP_W + G.MAP_H - 2; sum++) {
810:       for (let x = 0; x < G.MAP_W; x++) {
811:         const y = sum - x;
812:         if (y >= 0 && y < G.MAP_H) drawTile(x, y, t);
813:       }
814:     }
815: 
816:     drawRoads();
817:     drawPondReeds(t);
818:     drawCloudShadows(t);
819:     drawBuildMarkers(t);
820:     drawDemolishMarks(t);
821: 
822:     hitObjects.length = 0;
823:     const objs = [];
824:     for (const b of G.state.buildings) {
825:       if (b.type === 'road') continue;
826:       objs.push({ kind: 'building', b, depth: b.x + b.y + .01 });
827:     }
828:     for (const prop of G.scenery) {
829:       if (prop.decor && G.buildingAt(prop.x, prop.y)) continue;
830:       objs.push({ kind: 'scenery', prop, depth: sceneryDepth(prop) });
831:     }
832:     objs.sort((a, b) => a.depth - b.depth || (a.b?.x || 0) - (b.b?.x || 0));
833: 
834:     for (const o of objs) {
835:       if (o.kind === 'building') drawBuilding(o.b, t);
836:       else drawScenery(o.prop, t);
837:     }
838: 
839:     drawSmoke(t);
840:     drawSelection(t);
841:     drawHoverAndGhost(t);
842:     drawMotes(t);
843:     drawBirds(t);
844:     updateParticles(dt);
845:     drawParticles();
846: 
847:     requestAnimationFrame(render);
848:   }
