import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const url = process.env.CAPTURE_URL || 'http://localhost:3000/?v=4';
const out = process.env.OUT || '/tmp/opencode/desktop.png';
const width = +(process.env.W || 1440), height = +(process.env.H || 900);
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width, height } });
page.setDefaultTimeout(30000);
page.on('console', m => console.log('[console]', m.type(), m.text()));
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto(url, { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(2200);
const stats = await page.evaluate(() => ({
  fps: window.__kbFPS || null,
  zooms: window.KBG?.camera,
  buildings: window.KBG?.state?.buildings?.length,
  res: { ...window.KBG?.state?.res },
  pop: window.KBG?.state?.pop,
  level: window.KBG?.state?.level,
}));
console.log(JSON.stringify(stats, null, 2));
await page.screenshot({ path: out, timeout: 30000 });
console.log('saved', out);
await browser.close();

