function cacheSignature() {
  let scene = '';
  for (const b of G.state.buildings) {
    scene += b.id + b.type + b.level + b.x + '.' + b.y + ',';
  }
  return [vw, vh, DPR,
    G.camera.scale.toFixed(4),
    G.camera.ox.toFixed(2),
    G.camera.oy.toFixed(2),
    scene].join('|');
}

